SELECT * FROM (SELECT q.*, ROW_NUMBER() OVER (PARTITION BY q."deal_id" ORDER BY q."order_allocation" DESC, q."deal_name" ASC, q."investor_name" ASC, q."investor_id" ASC, q."order_demand_qty" ASC) AS "rank_in_group" FROM (SELECT "deal_name" AS "deal_name", "deal_id" AS "deal_id", "investor_name" AS "investor_name", "investor_gp_id" AS "investor_id", "order_demand_qty" AS "order_demand_qty", "order_allocation" AS "order_allocation", COUNT("order_id") AS "row_count" FROM "bds_dg_oraas"."dgstream"."vw_order_detail" WHERE "product" = __P_f0__ AND "deal_id" IN (__P_f1_0__, __P_f1_1__) GROUP BY "deal_name", "deal_id", "investor_name", "investor_gp_id", "order_demand_qty", "order_allocation") q) ranked WHERE "rank_in_group" <= 5 ORDER BY "order_allocation" DESC, "deal_id" ASC, "rank_in_group" ASC LIMIT 50
